fn momentum_sgd_rejects_logit_first_arg_with_hint() {
    let mut env = Environment::new();
    env.set("L".to_string(), DenseArray::from_scalar(2.5));
    env.set_tag("L".to_string(), mlpl_core::ValueTag::Logit);
