1	//! REPL introspection commands: `:vars`, `:models`, `:fns`, `:wsid`,
2	//! and `:describe <name>`. Shared between the terminal REPL
3	//! (`mlpl-repl`) and the web REPL (`mlpl-web` via `mlpl-wasm`) so
4	//! that both surfaces behave identically.
5	//!
6	//! These are inspired by APL's workspace conventions (`)VARS`,
7	//! `)FNS`, `)WSID`) but delivered as REPL commands rather than
8	//! language-level built-ins, so they stay out of the expression
9	//! grammar and never need to return a value.
10	
11	use mlpl_array::DenseArray;
12	use mlpl_core::LabeledShape;
13	
14	use crate::env::Environment;
15	use crate::model::{ActKind, ModelSpec};
16	
17	/// If `input` is a recognized introspection command, returns the
18	/// rendered output. Returns `None` when the command is not one of
19	/// ours -- the caller should pass it through its normal handling
20	/// path (error for unknown commands, etc.).
21	pub fn inspect(env: &Environment, input: &str) -> Option<String> {
22	    let trimmed = input.trim();
23	    if !trimmed.starts_with(':') {
24	        return None;
25	    }
26	    let mut parts = trimmed.split_whitespace();
27	    let head = parts.next()?;
28	    let arg = parts.next();
29	    match head {
30	        ":vars" | ":variables" => Some(format_vars(env)),
31	        ":models" => Some(format_models(env)),
32	        ":fns" | ":functions" => Some(
33	            "(no user-defined functions)\n\
34	             user functions are not yet a language feature; for the \
35	             built-in surface, use :builtins"
36	                .into(),
37	        ),
38	        ":builtins" | ":built-ins" => Some(format_builtins()),
39	        ":experiments" => Some(crate::experiment::format_registry(env)),
40	        ":version" => Some(format!(
41	            "MLPL v{} -- Array Programming Language for ML\n  \
42	             target: {}",
43	            env!("CARGO_PKG_VERSION"),
44	            std::env::consts::ARCH,
45	        )),
46	        ":wsid" => Some(format!(
47	            "workspace:\n  variables:       {}\n  parameters:      {}\n  \
48	             models:          {}\n  optimizer slots: {}",
49	            env.vars.len(),
50	            env.params.len(),
51	            env.models.len(),
52	            env.optim_state.buffers.len()
53	        )),
54	        ":describe" => Some(match arg {
55	            Some(name) => format_describe(env, name),
56	            None => "usage: :describe <name>".into(),
57	        }),
58	        ":help" => arg.and_then(|topic| help_topic(topic, env)),
59	        _ => None,
60	    }
61	}
62	
63	/// Resolve `:help <topic>` to a corresponding inspector output.
64	/// `:help` with no topic is handled by the REPL itself (it prints
65	/// the long-form cheatsheet); only `:help <topic>` lands here.
66	fn help_topic(topic: &str, env: &Environment) -> Option<String> {
67	    match topic {
68	        "vars" | "variables" => Some(format_vars(env)),
69	        "models" => Some(format_models(env)),
70	        "fns" | "functions" => Some(
71	            "(no user-defined functions)\n\
72	             user functions are not yet a language feature; for the \
73	             built-in surface, use :builtins"
74	                .into(),
75	        ),
76	        "builtins" | "built-ins" => Some(format_builtins()),
77	        "wsid" | "workspace" => Some(format!(
78	            "workspace:\n  variables:       {}\n  parameters:      {}\n  \
79	             models:          {}\n  optimizer slots: {}",
80	            env.vars.len(),
81	            env.params.len(),
82	            env.models.len(),
83	            env.optim_state.buffers.len()
84	        )),
85	        "describe" => Some(
86	            ":describe <name>\n  print the shape and a values preview \
87	             for a variable, the layer tree for a model, or the signature \
88	             and one-line doc for a built-in"
89	                .into(),
90	        ),
91	        _ => None,
92	    }
93	}
94	
95	fn format_vars(env: &Environment) -> String {
96	    if env.vars.is_empty() {
97	        return "(no variables bound)".into();
98	    }
99	    let mut names: Vec<&String> = env.vars.keys().collect();
100	    names.sort();
101	    let mut out = String::new();
102	    for name in names {
103	        let arr = &env.vars[name];
104	        let shape = format_shape(arr);
105	        let tag = if env.params.contains(name) {
106	            " [param]"
107	        } else {
108	            ""
109	        };
110	        out.push_str(&format!("  {name}: {shape}{tag}\n"));
111	    }
112	    out.truncate(out.trim_end().len());
113	    out
114	}
115	
116	fn format_models(env: &Environment) -> String {
117	    if env.models.is_empty() {
118	        return "(no models bound)".into();
119	    }
120	    let mut names: Vec<&String> = env.models.keys().collect();
121	    names.sort();
122	    let mut out = String::new();
123	    for name in names {
124	        let spec = &env.models[name];
125	        let param_count = spec.params().len();
126	        out.push_str(&format!(
127	            "  {name}: {} ({param_count} params)\n",
128	            render_spec(spec)
129	        ));
130	    }
131	    out.truncate(out.trim_end().len());
132	    out
133	}
134	
135	fn format_describe(env: &Environment, name: &str) -> String {
136	    if let Some(tok) = env.tokenizers.get(name) {
137	        return format!("{name} -- tokenizer\n  {}", tok.describe());
138	    }
139	    if let Some(spec) = env.models.get(name) {
140	        let mut out = format!("{name} -- model\n  shape: {}\n", render_spec(spec));
141	        let ps = spec.params();
142	        if ps.is_empty() {
143	            out.push_str("  params: (none)");
144	        } else {
145	            out.push_str("  params:\n");
146	            for p in ps {
147	                if let Some(arr) = env.vars.get(&p) {
148	                    out.push_str(&format!("    {p}: {}\n", format_shape(arr)));
149	                }
150	            }
151	            out.truncate(out.trim_end().len());
152	        }
153	        return out;
154	    }
155	    if let Some(arr) = env.vars.get(name) {
156	        let shape = format_shape(arr);
157	        let tag = if env.params.contains(name) {
158	            " (trainable param)"
159	        } else {
