            std::env::consts::ARCH,
        )),
        ":wsid" => Some(format!(
            "workspace:\n  variables:       {}\n  parameters:      {}\n  \
             models:          {}\n  optimizer slots: {}",
            env.vars.len(),
            env.params.len(),
            env.models.len(),
