16	pub(crate) fn header_line(tag: &ValueTag) -> String {
17	    match tag {
18	        ValueTag::Logit | ValueTag::Probability | ValueTag::LogProbability => {
19	            tag.display_name().into()
20	        }
21	        ValueTag::Loss { kind } => format!("Loss({})", loss_kind_str(*kind)),
22	        ValueTag::Gradient { wrt } => format!("Gradient(wrt={wrt})"),
23	        ValueTag::Weight { layer, name } => {
24	            format!("Weight(layer={layer}, name={name})")
25	        }
26	        ValueTag::Bias { layer } => format!("Bias(layer={layer})"),
27	        ValueTag::Activation { layer, kind } => format!(
28	            "Activation(layer={layer}, kind={})",
