37	/// Per-tag body lines for `:describe`. Probability includes a
38	/// row-sum invariant check; AttentionMap notes the heatmap
39	/// rendering; Loss / Gradient / Activation reiterate metadata.
40	pub(crate) fn body_lines(tag: &ValueTag, arr: Option<&DenseArray>) -> Vec<String> {
41	    match tag {
42	        ValueTag::Probability => arr
43	            .map(|a| vec![probability_invariant(a)])
44	            .unwrap_or_default(),
