46	            vec!["renders as a heatmap via svg(att, \"heatmap\")".into()]
47	        }
48	        ValueTag::Loss { kind } => vec![format!(
49	            "scalar loss; produced by the {} family",
50	            loss_kind_op(*kind)
51	        )],
52	        ValueTag::Gradient { wrt } => vec![format!(
53	            "gradient w.r.t. parameter `{wrt}` (consumed by adam / momentum_sgd)"
54	        )],
55	        ValueTag::Weight { .. } => vec!["trainable parameter (matrix)".into()],
56	        ValueTag::Bias { .. } => vec!["trainable parameter (bias row)".into()],
57	        ValueTag::Activation { kind, .. } => vec![format!(
58	            "hidden activation, kind={}",
