60	        )],
61	        ValueTag::Labels { num_classes } => vec![format!(
62	            "integer-valued class indices in [0, {num_classes})"
63	        )],
64	        ValueTag::Logit => vec!["unnormalized scores; bridge with softmax(_, axis)".into()],
65	        ValueTag::LogProbability => {
66	            vec!["log-probabilities; bridge with exp() to recover Probability".into()]
67	        }
