72	/// `:tags` listing. Walks `Environment::tags`, sorts by name,
73	/// and renders one line per binding using `header_line`.
74	pub(crate) fn format_tags(env: &Environment) -> String {
75	    let mut entries: Vec<(&String, &ValueTag)> = env.tags_iter().collect();
76	    if entries.is_empty() {
77	        return "(no tagged bindings)".into();
78	    }
79	    entries.sort_by(|a, b| a.0.cmp(b.0));
80	    let mut out = String::new();
81	    for (name, tag) in entries {
82	        out.push_str(&format!("  {name}: {}\n", header_line(tag)));
83	    }
