106	fn activation_kind_str(k: ActivationKind) -> &'static str {
107	    match k {
108	        ActivationKind::Tanh => "Tanh",
109	        ActivationKind::Relu => "Relu",
110	        ActivationKind::Sigmoid => "Sigmoid",
111	        ActivationKind::Softmax => "Softmax",
