114	
115	fn probability_invariant(arr: &DenseArray) -> String {
116	    let dims = arr.shape().dims();
117	    if dims.is_empty() {
118	        return "row-sum invariant: scalar (skipped)".into();
119	    }
120	    let last = *dims.last().unwrap_or(&0);
121	    if last == 0 {
122	        return "row-sum invariant: empty (skipped)".into();
123	    }
124	    let data = arr.data();
125	    let n_rows = data.len() / last;
126	    let mut max_dev = 0.0f64;
127	    for r in 0..n_rows {
128	        let row = &data[r * last..(r + 1) * last];
129	        let s: f64 = row.iter().sum();
130	        let dev = (s - 1.0).abs();
131	        if dev > max_dev {
132	            max_dev = dev;
133	        }
134	    }
135	    if max_dev <= 1e-5 {
136	        format!("row-sum invariant: verified (max deviation {max_dev:.2e})")
137	    } else {
138	        format!("row-sum invariant: violated (max deviation {max_dev:.2e}; rows do not sum to 1)")
139	    }
140	}

