/// trace event from the expression that produced it. For
/// Assign expressions, the output type is the just-set tag on
/// the binding; input types come from FnCall args that are
/// bare identifiers (their tags can be looked up). Other
/// expression kinds yield empty / None.
fn trace_types_for(
    expr: &mlpl_parser::Expr,
    env: &Environment,
) -> (Vec<Option<mlpl_core::ValueTag>>, Option<mlpl_core::ValueTag>) {
    let mlpl_parser::Expr::Assign { name, value, .. } = expr else {
        return (Vec::new(), None);
    };
    let output_type = env.get_tag(name).cloned();
    let input_types = match value.as_ref() {
        mlpl_parser::Expr::FnCall { args, .. } => args
            .iter()
            .map(|a| match a {
                mlpl_parser::Expr::Ident(n, _) => env.get_tag(n).cloned(),
                _ => None,
            })
            .collect(),
        _ => Vec::new(),
    };
    (input_types, output_type)
}

