fn trace_value_from_scalar_array() {
    use mlpl_array::DenseArray;
    let arr = DenseArray::from_scalar(7.0);
    let val = TraceValue::from_array(&arr);
    assert_eq!(val, TraceValue::Scalar { value: 7.0 });
}

