                ValueTag::LogProbability => HINT_LOGIT_GOT_LOG_PROBABILITY,
                ValueTag::Labels { .. } if op == "cross_entropy" => HINT_LOGIT_GOT_LABELS,
                _ => return Ok(()),
            };
            Err(EvalError::TypeMismatch {
                op: op.into(),
                expected: "Logit".into(),
                actual: tag.display_name().into(),
                hint: hint.into(),
            })
        }
    }
}

