81	    try_run("Y = matmul(X, W)\n", &mut env).unwrap();
82	    try_run("g = grad(mean(Y), W)\n", &mut env).unwrap();
83	    assert_eq!(
84	        env.get_tag("g"),
85	        Some(&ValueTag::Gradient {
86	            wrt: "W".to_string()
87	        })
88	    );
89	}
