91	#[test]
92	fn lesson_step_5_tag_propagates_through_addition() {
93	    let mut env = Environment::new();
94	    try_run("L1 = randn(3, [2, 3])\n", &mut env).unwrap();
95	    try_run("L2 = randn(4, [2, 3])\n", &mut env).unwrap();
96	    // Pretend the user has tagged L1 and L2 as Logit; the
97	    // lesson uses softmax-then-untag in the visible flow,
98	    // but the propagation rule fires regardless.
99	    env.set_tag("L1".into(), ValueTag::Logit);
100	    env.set_tag("L2".into(), ValueTag::Logit);
101	    try_run("sum_logits = L1 + L2\n", &mut env).unwrap();
102	    assert_eq!(env.get_tag("sum_logits"), Some(&ValueTag::Logit));
