106	fn lesson_step_6_logit_plus_probability_raises_domain_mismatch() {
107	    let mut env = Environment::new();
108	    try_run("L_tag = randn(5, [2, 3])\n", &mut env).unwrap();
109	    try_run("P_tag = softmax(L_tag, 1)\n", &mut env).unwrap();
110	    env.set_tag("L_tag".into(), ValueTag::Logit);
111	    let err = try_run("mix = L_tag + P_tag\n", &mut env).unwrap_err();
112	    assert!(matches!(err, EvalError::TypeMismatch { .. }), "got {err:?}");
