115	#[test]
116	fn lesson_step_7_apply_softmax_layer_tail_yields_probability() {
117	    let mut env = Environment::new();
118	    try_run("mdl = chain(linear(3, 4, 0), softmax_layer())\n", &mut env).unwrap();
119	    try_run("out = apply(mdl, randn(0, [2, 3]))\n", &mut env).unwrap();
120	    assert_eq!(env.get_tag("out"), Some(&ValueTag::Probability));
