123	#[test]
124	fn lesson_step_8_untag_clears_tag() {
125	    let mut env = Environment::new();
126	    try_run("x = randn(0, [2, 3])\n", &mut env).unwrap();
127	    env.set_tag("x".into(), ValueTag::Logit);
128	    let out = inspect(&mut env, ":untag x").unwrap();
129	    assert!(out.to_lowercase().contains("untagged"), "out: {out}");
130	    assert!(env.get_tag("x").is_none(), "tag should be cleared");
131	}
