134	fn lesson_step_9_tags_lists_tagged_bindings() {
135	    let mut env = Environment::new();
136	    try_run("L = randn(0, [2, 3])\n", &mut env).unwrap();
137	    try_run("probs = softmax(L, 1)\n", &mut env).unwrap();
138	    let out = inspect(&mut env, ":tags").unwrap();
